std::vector<uint16_t> read(const char* file,size_t cells){
    std::ifstream stream(file,std::ios::binary|std::ios::ate);
    if(!stream||stream.tellg()!=std::streamoff(cells*2u))throw std::runtime_error("tensor extent");
    std::vector<uint16_t> values(cells);stream.seekg(0);
    stream.read(reinterpret_cast<char*>(values.data()),std::streamsize(cells*2u));
    if(!stream)throw std::runtime_error("tensor read");
    return values;
}
