    const unsigned rows=mode=="qkv"?8192u:2048u,width=mode=="qkv"?2048u:4096u;
    const auto inputs=read(argv[2],size_t(8192u)*width);
    const auto weights=read(argv[3],size_t(rows)*width);
    const auto reference=read(argv[4],size_t(8192u)*rows);
    std::vector<unsigned> rejected_inputs,rejected_weights;
    unsigned invalid_input_cells=0u,invalid_weight_cells=0u;
