    auto dot=[&](unsigned token,unsigned row){
        const uint16_t* a=inputs.data()+size_t(token)*width;
        const uint16_t* b=weights.data()+size_t(row)*width;
        original::Value carry{0u,-133,false};
        for(unsigned group=0;group<width/16u;++group){
            original::Value terms[17];terms[0]=carry;
            for(unsigned i=0;i<16u;++i)terms[i+1u]=original::multiply_bf16(a[group*16u+i],b[group*16u+i],-133);
