    for(unsigned row:rejected_weights)for(unsigned sample=0;sample<16u;++sample){
        const unsigned token=sample*8191u/15u;
        if(std::find(rejected_inputs.begin(),rejected_inputs.end(),token)==rejected_inputs.end())dot(token,row);
    }
    if(finite_failures)throw std::runtime_error("nonfinite output");
    std::cout<<"{\"mode\":\""<<mode<<"\",\"source_tokens\":8192,\"repeated_rows\":0,\"rejected_input_rows\":[";
    for(size_t i=0;i<rejected_inputs.size();++i)std::cout<<(i?",":"")<<rejected_inputs[i];
    std::cout<<"],\"rejected_weight_rows\":[";
    for(size_t i=0;i<rejected_weights.size();++i)std::cout<<(i?",":"")<<rejected_weights[i];
