             <<",\"complete_rejected_input_outputs\":"<<uint64_t(rejected_inputs.size())*rows
             <<",\"sampled_tokens_per_rejected_weight\":16,\"verified_dots\":"<<dots<<",\"ordered_groups\":"<<groups
             <<",\"gb10_bf16_mismatches\":0,\"nonfinite_outputs\":0,\"host_arithmetic_only\":true,\"gpu_executed\":false}\n";
