using I4=int __attribute__((ext_vector_type(4)));
using I8=int __attribute__((ext_vector_type(8)));
using F8=float __attribute__((ext_vector_type(8)));
struct Dimension {unsigned x=0u;};
thread_local Dimension threadIdx,blockIdx;
struct Wave {
    std::barrier<> sync{32};
    uint32_t words[32]{};
    unsigned kinds[32]{};
    I4 left[32]{},right[32]{};
    unsigned signs[32]{};
    uint64_t shuffles=0u,ballots=0u,matrices=0u;
};
thread_local Wave* wave=nullptr;
void enter(unsigned kind){
    wave->kinds[threadIdx.x%32u]=kind;
    wave->sync.arrive_and_wait();
    for(unsigned lane=0u;lane<32u;++lane)if(wave->kinds[lane]!=kind)std::terminate();
}
unsigned __ballot(bool value){
    const unsigned lane=threadIdx.x%32u;
    wave->words[lane]=value;
    enter(1u);
    unsigned mask=0u;for(unsigned source=0u;source<32u;++source)mask|=wave->words[source]<<source;
    if(!lane)++wave->ballots;
    wave->sync.arrive_and_wait();
    return mask;
}
uint32_t __shfl(uint32_t value,unsigned source){
    if(source>=32u)std::terminate();
    const unsigned lane=threadIdx.x%32u;
    wave->words[lane]=value;
    enter(2u);
    const auto result=wave->words[source];
    if(!lane)++wave->shuffles;
    wave->sync.arrive_and_wait();
    return result;
}
I8 modeled_wmma(bool signed_left,I4 left,bool signed_right,I4 right,I8 accumulator,bool clamp){
    const unsigned lane=threadIdx.x%32u;
    wave->left[lane]=left;wave->right[lane]=right;
    wave->signs[lane]=unsigned(signed_left)|unsigned(signed_right)<<1u|unsigned(clamp)<<2u;
    enter(3u);
    for(unsigned source=0u;source<32u;++source){
        if(wave->signs[source]!=wave->signs[lane]||clamp)std::terminate();
        for(unsigned word=0u;word<4u;++word){
            if(wave->left[source][word]!=wave->left[source%16u][word]||
               wave->right[source][word]!=wave->right[source%16u][word])std::terminate();
        }
    }
    auto byte=[](int value,unsigned index,bool sign){
        const unsigned part=(uint32_t(value)>>(index*8u))&255u;
        return sign&&part>=128u?int(part)-256:int(part);
    };
    I8 result{};
    for(unsigned item=0u;item<8u;++item){
        const unsigned row=item*2u+lane/16u,column=lane%16u;
        int sum=accumulator[item];
        for(unsigned k=0u;k<16u;++k)sum+=byte(wave->left[row][k/4u],k%4u,signed_left)*
                                               byte(wave->right[column][k/4u],k%4u,signed_right);
        result[item]=sum;
    }
    if(!lane)++wave->matrices;
    wave->sync.arrive_and_wait();
    return result;
}
