struct Count {uint64_t cases=0,selected=0,carries=0,inactive=0,shuffles=0,ballots=0,matrices=0;};
template<bool Force>void check(unsigned rows,unsigned tokens,unsigned width,unsigned family,unsigned pattern,Count& counts){
    const unsigned groups=width/16u;
    std::vector<uint16_t> weights(size_t(rows)*width),inputs(size_t(tokens)*width);
    for(unsigned side=0u;side<2u;++side){
        auto& raw=side?inputs:weights;
        for(size_t i=0u;i<raw.size();++i){
            unsigned exponent=family==0u?127u:(95u+unsigned((i*17u+(i/width)*7u+side*19u)%65u));
            raw[i]=uint16_t(((i+side)&1u?0x8000u:0u)|(exponent<<7u)|((i*13u+side*11u)%128u));
            if(i%29u==0u)raw[i]=uint16_t(i&1u?0x8000u:0u);
        }
        if(family==2u)raw.back()=0x2f01u; // Unsupported final group, retained inactive here.
    }
    std::vector<partial::Row> wp(size_t(rows)*groups),xp(size_t(tokens)*groups);
    std::vector<unsigned> wf(rows,1u),xf(tokens,1u);
    for(unsigned side=0u;side<2u;++side){
        const auto& raw=side?inputs:weights;auto& packed=side?xp:wp;auto& flags=side?xf:wf;
        const unsigned count=side?tokens:rows;
        for(unsigned row=0u;row<count;++row)for(unsigned group=0u;group<groups;++group){
            packed[size_t(group)*count+row]=partial::prepare(raw.data()+size_t(row)*width+group*16u);
            for(unsigned i=0u;i<16u;++i)flags[row]&=qrt_sm121_narrow_f32_carry::eligible(raw[size_t(row)*width+group*16u+i]);
        }
    }
    const auto wp_before=wp,xp_before=xp;const auto wf_before=wf,xf_before=xf;
    const size_t cells=size_t(rows)*tokens;
    std::vector<unsigned> bitmap((cells+31u)/32u,0u);
    for(size_t cell=0u;cell<cells;++cell){
        const unsigned row=unsigned(cell%rows),token=unsigned(cell/rows);
        const bool selected=pattern==2u||(pattern==1u&&((row%16u==15u&&token%16u==7u)||cell==0u||cell==cells-1u));
        if(selected)bitmap[cell/32u]|=1u<<(cell%32u);
    }
    const auto bitmap_before=bitmap;
    std::vector<float> outputs(cells+16u,as_float(untouched));
    std::vector<uint32_t> trace(cells*groups+16u,untouched);
    const unsigned tiles=((rows+15u)/16u)*((tokens+15u)/16u);
    // Include unused final waves of the final CTA to exercise uniform returns.
    for(unsigned tile=0u;tile<((tiles+3u)/4u)*4u;++tile){
        Wave model;std::vector<std::thread> workers;
        for(unsigned lane=0u;lane<32u;++lane)workers.emplace_back([&,lane]{
            threadIdx.x=(tile%4u)*32u+lane;blockIdx.x=tile/4u;wave=&model;
            qrt_sm121_partial_wave_projection::replay<true,Force>(wp.data(),xp.data(),wf.data(),xf.data(),
                bitmap.data(),outputs.data()+8u,trace.data()+8u,rows,tokens,width);
        });
        for(auto& worker:workers)worker.join();
        counts.shuffles+=model.shuffles;counts.ballots+=model.ballots;counts.matrices+=model.matrices;
    }
    for(size_t cell=0u;cell<cells;++cell){
        const unsigned row=unsigned(cell%rows),token=unsigned(cell/rows);
        const bool selected=((bitmap[cell/32u]>>(cell%32u))&1u)&&wf[row]&&xf[token];
        if(!selected){
            if(float_bits(outputs[cell+8u])!=untouched)throw std::runtime_error("inactive output changed");
            for(unsigned group=0u;group<groups;++group)if(trace[8u+cell*groups+group]!=untouched)throw std::runtime_error("inactive trace changed");
            ++counts.inactive;continue;
        }
        original::Value carry{0u,-133,false};
        for(unsigned group=0u;group<groups;++group){
            original::Value terms[17];terms[0]=carry;
            for(unsigned i=0u;i<16u;++i)terms[i+1u]=original::multiply_bf16(
                inputs[size_t(token)*width+group*16u+i],weights[size_t(row)*width+group*16u+i],-133);
            carry=original::group_sum<26,-133>(terms,17u);
            if(trace[8u+cell*groups+group]!=float_bits(original::value_to_float(carry)))throw std::runtime_error("ordered carry differs");
            ++counts.carries;
        }
        if(float_bits(outputs[8u+cell])!=float_bits(original::value_to_float(carry)))throw std::runtime_error("output differs");
        ++counts.selected;
    }
    for(unsigned i=0u;i<8u;++i)if(float_bits(outputs[i])!=untouched||float_bits(outputs[8u+cells+i])!=untouched||
        trace[i]!=untouched||trace[8u+cells*groups+i]!=untouched)throw std::runtime_error("redzone changed");
    if(wf!=wf_before||xf!=xf_before||bitmap!=bitmap_before||
        std::memcmp(wp.data(),wp_before.data(),wp.size()*sizeof(partial::Row))||
        std::memcmp(xp.data(),xp_before.data(),xp.size()*sizeof(partial::Row)))throw std::runtime_error("input changed");
    ++counts.cases;
}
int main()try{
