    const unsigned shapes[][3]={{1u,1u,16u},{17u,19u,32u},{33u,17u,16u},{16u,16u,272u}};
    for(const auto& s:shapes)for(unsigned family=0u;family<3u;++family)for(unsigned pattern=0u;pattern<3u;++pattern){
        check<false>(s[0],s[1],s[2],family,pattern,counts);
        check<true>(s[0],s[1],s[2],family,pattern,counts);
    }
    std::cout<<"{\"cases\":"<<counts.cases<<",\"selected_outputs\":"<<counts.selected<<",\"ordered_carries\":"<<counts.carries
      <<",\"inactive_outputs\":"<<counts.inactive<<",\"uniform_shuffles\":"<<counts.shuffles<<",\"uniform_ballots\":"<<counts.ballots
      <<",\"modeled_matrix_instructions\":"<<counts.matrices<<",\"raw_bit_mismatches\":0,\"redzones_pass\":true,\"immutable_inputs\":true"
      <<",\"host_coordinates_and_declared_matrix_model_only\":true,\"physical_wmma_semantics_verified\":false,\"gpu_executed\":false}\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}
